@CrossOrigin
@RestController
@RequestMapping("/FacilityQuery")
public class FacilityQueryRestController extends BaseSpringRestController {
	
	public FacilityQueryRestController( FacilityService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Facility using a UUID
     * @param		UUID facilityId
     * @return		Facility
     */    
    @GetMapping("/load")
    public Facility load( @RequestParam(required=true) UUID facilityId ) {
    	Facility entity = null;

    	try {  
    		entity = service.getFacility( new FacilityFetchOneSummary( facilityId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Facility using Id " + facilityId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Facility business objects
     * @return		Set<Facility>
     */
    @GetMapping("/")
    public List<Facility> loadAll() {                
    	List<Facility> facilityList = null;
        
    	try {
            // load the Facility
            facilityList = service.getAllFacility();
            
            if ( facilityList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Facilitys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Facilitys ", exc );
        	return null;
        }

        return facilityList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Facility facility = null;
    protected FacilityService service = null;
    private static final Logger LOGGER = Logger.getLogger(FacilityQueryRestController.class.getName());
    
}
